import {modules,facts} from './content.js';
import {specimens} from './specimens.js';
import {shuffled,normalize} from '../chapter3/engine.js';
export const blueprint={types:6,epithelial:10,connective:10,muscle:5,nervous:4,repair:5};
const scenario=(id,module,lesson,prompt,answer,others,explanation,visual)=>({id:`${module}/case/${id}`,module,lesson,prompt,answer,options:[answer,...others],explanation,type:'reasoning',visual});
export const cases=[
 scenario('mixed-organ','types','families','A stomach wall contains a lining, supporting matrix, contractile layers and nerves. What does this illustrate?','An organ combines several tissue types',['Each organ contains only one tissue type','Every layer is epithelial tissue','An organ is a single specialized cell'],'Organs combine tissues with complementary functions.'),
 scenario('serosa','types','membranes','A slippery membrane covers an organ in a closed ventral cavity. Which membrane fits?','Serous membrane',['Mucous membrane','Synovial membrane','Cutaneous membrane'],'Serous membranes reduce friction in closed ventral cavities; mucous membranes line passages open to the exterior.'),
 scenario('origin','types','origins','Which statement correctly connects epithelium to embryonic origin?','Epithelia can arise from all three germ layers',['Every epithelium arises from ectoderm','Every epithelium arises from endoderm','Germ layers are four adult tissue families'],'Developmental origin and adult tissue classification are different questions.'),
 scenario('layers','epithelial','classification','Which name matches the illustrated sheet?','Simple cuboidal epithelium',['Stratified cuboidal epithelium','Simple squamous epithelium','Simple columnar epithelium'],'There is one layer, with cells approximately as tall as wide.',{module:'epithelial',mode:'classifier',layers:1,shape:'cuboidal'}),
 scenario('flat','epithelial','classification','Which visible feature most strongly supports a simple squamous classification?','One layer of flattened cells',['Many layers with tall surface cells','Branching striated fibers','A network of extracellular collagen'],'The diagram shows a single thin layer, suited to a short exchange distance.',{module:'epithelial',mode:'classifier',layers:1,shape:'squamous'}),
 scenario('top','epithelial','classification','When naming a stratified epithelium, which cells determine the shape part of its name?','The apical cells',['The deepest cells only','The cells with the largest nuclei','The underlying fibroblasts'],'Stratified epithelia are named by the cells at the free surface.'),
 scenario('pseudo','epithelial','special','Nuclei occur at different heights, but all cells touch the basal lamina. What is the best interpretation?','Pseudostratified epithelium',['True stratified epithelium','Loose connective tissue','Transitional tissue must be present'],'Uneven nuclear heights alone do not establish multiple layers.'),
 scenario('stretch','epithelial','special','After bladder filling, surface cells appear flatter. What changed?','The shape and apparent thickness of transitional epithelium',['The tissue became simple squamous epithelium','The cells became connective tissue','Every basal cell was shed'],'Stretch alters appearance while the tissue remains transitional.'),
 scenario('exchange','epithelial','locations','Why does a very thin epithelial lining suit alveolar gas exchange?','It shortens the diffusion distance',['It adds many protective layers','It produces contractile force','It prevents all molecular movement'],'Simple squamous architecture minimizes the distance across the epithelial barrier.'),
 scenario('gland-duct','epithelial','glands','A gland has several secretory sacs emptying into one unbranched duct. What can you conclude?','The duct system is simple',['The duct system must be compound','The gland must be endocrine','The release mechanism must be holocrine'],'Simple versus compound describes the duct branching, not the number of secretory sacs.'),
 scenario('vesicle','epithelial','secretion','A secretory cell releases vesicle contents and remains intact. Which mechanism is operating?','Merocrine secretion',['Apocrine secretion','Holocrine secretion','Necrosis'],'Exocytosis releases the product without sacrificing an apical fragment or the whole cell.'),
 scenario('nutrients','epithelial','polarity','An epithelium has no blood vessels. How can its cells obtain nutrients?','Diffusion from the underlying connective tissue',['Every epithelial cell contains a capillary','Nutrients are unnecessary','Only gap junctions deliver blood'],'Avascular tissue can receive nutrients by diffusion from nearby vascular tissue.'),
 scenario('parallel','connective','dense','Which tissue arrangement is illustrated?','Dense regular connective tissue',['Dense irregular connective tissue','Hyaline cartilage','Simple columnar epithelium'],'The prominent bundles are largely parallel rather than woven in multiple directions.',{module:'connective',mode:'regular'}),
 scenario('woven','connective','dense','Which visible feature supports resistance to tension from several directions?','Interwoven collagen bundles',['One parallel set of fibers only','A single thin epithelial layer','Absence of extracellular matrix'],'Different bundle orientations distribute resistance across several directions.',{module:'connective',mode:'irregular'}),
 scenario('ear','connective','cartilage','An external ear must hold its shape yet bend. Which cartilage is well suited?','Elastic cartilage',['Fibrocartilage','Hyaline cartilage','Dense regular connective tissue'],'Elastic fibers support flexibility with return toward the original shape.'),
 scenario('disc','connective','cartilage','Which matrix is suited to an intervertebral disc resisting compression?','Fibrocartilage with thick collagen bundles',['A thin simple squamous lining','A liquid plasma matrix','A sheet of keratinized surface cells'],'Fibrocartilage combines a firm matrix with thick collagen bundles suited to compressive loading.'),
 scenario('repair','connective','cartilage','Why does cartilage commonly repair slowly?','It lacks its own blood vessels',['Its matrix is liquid','Its cells lack nuclei','Every injury becomes bone immediately'],'Avascular cartilage depends on diffusion, limiting delivery compared with vascular tissues.'),
 scenario('blood-matrix','connective','bone-blood','Which pairing correctly identifies a connective tissue and its matrix?','Blood — plasma',['Blood — erythrocytes','Cartilage — chondrocytes','Bone — osteocytes'],'Cells are embedded in matrix; plasma is the extracellular liquid of blood.'),
 scenario('adipocyte','connective','loose','A prepared adipose specimen contains large clear spaces with thin cell rims. Why might lipid look empty?','Preparation can remove stored lipid',['The tissue had no living cells','All clear areas are blood vessels','The tissue must be cartilage'],'Processing can extract lipid, so specimen appearance differs from the living cell.'),
 scenario('cardiac','muscle','compare','Which muscle type is shown in this textbook micrograph?','Cardiac muscle',['Skeletal muscle','Smooth muscle','Dense regular connective tissue'],'Striations, central nuclei and branching support cardiac muscle. Intercalated discs distinguish cardiac tissue but may not be clearly resolved in every field.',{module:'muscle',mode:'cardiac'}),
 scenario('smooth','muscle','compare','Which tissue matches spindle-shaped cells without visible striations?','Smooth muscle',['Skeletal muscle','Cardiac muscle','Stratified squamous epithelium'],'Smooth muscle combines a spindle shape with a single central nucleus and no visible striations.',{module:'muscle',mode:'smooth'}),
 scenario('striated','muscle','compare','A student sees stripes and immediately answers “skeletal.” What evidence is still needed?','Cell shape, nuclear position and branching',['Whether any matrix exists anywhere','The age of the student','Whether all nuclei are absent'],'Both skeletal and cardiac muscle are striated; additional features distinguish them.'),
 scenario('control','muscle','function','Which muscle moves material along much of the digestive tract?','Involuntary smooth muscle',['Voluntary cardiac muscle','Only skeletal muscle','No muscle is involved'],'Smooth muscle in hollow organs contracts without conscious initiation.'),
 scenario('flow','nervous','neuron','Which is the typical information-flow order?','Dendrites → cell body → axon',['Axon → nucleus → dendrites only','Myelin → blood → bone','Cell body → collagen → dendrites'],'The simplified pathway runs from receptive processes toward the soma and along an axon to output sites.'),
 scenario('central','nervous','glia','Damage affects myelin produced by oligodendrocytes. Which setting fits?','Central nervous system',['Peripheral nerve only','Epidermis','Cartilage'],'Oligodendrocytes form CNS myelin; Schwann cells form PNS myelin.'),
 scenario('uncertain-image','nervous','neuron','A micrograph shows a neuronal process but no clear identifying landmarks. What is the strongest conclusion?','More evidence is needed to distinguish axon from dendrite',['Every thin process is an axon','Every process is a dendrite','The tissue cannot contain glia'],'Do not infer more than the visible evidence supports.'),
 scenario('redness','repair','inflammation','Which mechanism most directly explains redness and heat around an injury?','Increased local blood flow',['Loss of all capillaries','Immediate mineralization','Reduced cell number alone'],'Vasodilation increases local flow; vascular permeability contributes more directly to swelling.'),
 scenario('scar','repair','healing','A wound closes with collagen-rich tissue but lacks the original glands. Which interpretation fits?','Fibrosis restored continuity without complete functional regeneration',['Every original function was necessarily restored','The tissue became cartilage','Healing did not occur at all'],'Scar tissue can restore continuity and some strength without reproducing the original architecture.'),
 scenario('death','repair','death-aging','Cells dismantle in a regulated way and are removed without widespread inflammation. Which process fits?','Apoptosis',['Necrosis','Metastasis','Hyperplasia'],'Controlled removal differs from damaging membrane breakdown in necrosis.'),
 scenario('growth','repair','organization','An increased number of cells is reported. Does that alone establish cancer?','No; hyperplasia alone does not establish malignancy',['Yes; any extra cell is malignant','Yes; every increase means metastasis','No tissue can increase its cell number'],'Malignancy involves more than cell number, including invasive behavior.'),
];
export const bank=[...facts.map(f=>{
 const peers=facts.filter(x=>x.module===f.module&&x.id!==f.id);
 const start=peers.findIndex(x=>x.lesson===f.lesson);
 const distractors=[...peers.slice(Math.max(0,start)),...peers.slice(0,Math.max(0,start))].slice(0,3).map(x=>x.term);
 return {id:`${f.module}/term/${f.id}`,module:f.module,lesson:f.lesson,type:'recall',prompt:`Which term matches this description? ${f.definition}`,answer:f.term,options:[f.term,...distractors],explanation:f.definition};
}),...cases,...specimens.flatMap(s=>[
 {id:`${s.module}/specimen/${s.id}/name`,module:s.module,lesson:s.lesson,type:'specimen',specimen:s.id,prompt:'Identify the tissue in this textbook micrograph.',answer:s.name,options:s.module==='muscle'?['Skeletal muscle','Smooth muscle','Cardiac muscle','Dense regular connective tissue']:['Adipose tissue','Reticular tissue','Hyaline cartilage','Simple cuboidal epithelium'],explanation:s.evidence+' '+s.contrast},
 {id:`${s.module}/specimen/${s.id}/evidence`,module:s.module,lesson:s.lesson,type:'evidence',specimen:s.id,prompt:'Which visible evidence best supports the identification of this tissue?',answer:s.evidence,options:[s.evidence,...specimens.filter(x=>x.id!==s.id).slice(0,3).map(x=>x.evidence)],explanation:s.name+': '+s.evidence+' '+s.contrast}
])];
export function makeSession({module,exam=false,stats={},revisit=false,random=Math.random}={}){
 let pool=bank.filter(q=>(!module||q.module===module)&&(!revisit||(stats[q.id]&&(!stats[q.id].lastCorrect||stats[q.id].assisted))));
 if(exam){pool=Object.entries(blueprint).flatMap(([id,n])=>{const group=pool.filter(q=>q.module===id),visual=shuffled(group.filter(q=>q.type==='specimen'),random).slice(0,1),reasoning=shuffled(group.filter(q=>q.type==='reasoning'),random).slice(0,Math.min(3,n-visual.length)),chosen=[...visual,...reasoning],rest=group.filter(q=>!chosen.includes(q)&&(!q.specimen||!chosen.some(x=>x.specimen===q.specimen)));return [...chosen,...shuffled(rest,random).filter((q,i,a)=>!q.specimen||a.findIndex(x=>x.specimen===q.specimen)===i).slice(0,n-chosen.length)];});}
 else pool=shuffled(pool,random).slice(0,10);
 return {version:1,exam,ids:shuffled(pool,random).map(q=>q.id),options:Object.fromEntries(pool.map(q=>[q.id,shuffled(q.options,random)])),answers:{},assisted:{},index:0,submitted:false,recorded:{}};
}
export const correct=(q,value)=>!!value&&normalize(value)===normalize(q.answer);
export function result(session){const rows=session.ids.map(id=>({id,correct:correct(bank.find(q=>q.id===id),session.answers[id]),assisted:!!session.assisted[id]}));return {rows,total:rows.length,independent:rows.filter(r=>r.correct&&!r.assisted).length,assisted:rows.filter(r=>r.correct&&r.assisted).length,missed:rows.filter(r=>!r.correct||r.assisted).length};}
export function validSession(s){return !!s&&s.version===1&&Array.isArray(s.ids)&&s.ids.length>0&&s.ids.length<=40&&new Set(s.ids).size===s.ids.length&&s.ids.every(id=>bank.some(q=>q.id===id))&&Number.isInteger(s.index)&&s.index>=0&&s.index<s.ids.length&&s.answers&&typeof s.answers==='object'&&s.options&&s.ids.every(id=>Array.isArray(s.options[id])&&s.options[id].length===4&&new Set(s.options[id]).size===4&&s.options[id].every(v=>bank.find(q=>q.id===id).options.includes(v)))&&s.assisted&&s.recorded;}
export const sectionCounts=Object.fromEntries(modules.map(m=>[m.id,bank.filter(q=>q.module===m.id).length]));
